[{"order":1,"type":"heading","text":"Vite Integration & Preprocessors in Svelte"},{"order":2,"type":"paragraph","text":"Svelte and Vite provide a lightning-fast development experience out of the box. By leveraging Vite's native plugin system and preprocessors like SCSS, TypeScript, and PostCSS, you can significantly enhance your Svelte applications."},{"order":3,"type":"subheading","text":"1. Setting up Svelte with Vite"},{"order":4,"type":"paragraph","text":"When creating a new Svelte project using Vite, the official template configures everything automatically. You can initialize a project using npm with the following command:"},{"order":5,"type":"code","text":"npm create vite@latest my-svelte-app -- --template svelte"},{"order":6,"type":"subheading","text":"2. Installing Preprocessors"},{"order":7,"type":"paragraph","text":"To use preprocessors like SCSS or Less inside your Svelte single-file components (.svelte), you need to install 'svelte-preprocess' along with the specific preprocessor library."},{"order":8,"type":"code","text":"npm install -D svelte-preprocess sass"},{"order":9,"type":"subheading","text":"3. Configuring vite.config.js"},{"order":10,"type":"paragraph","text":"Next, integrate the preprocessors into your Vite configuration file so the Svelte plugin knows how to parse non-standard style and script blocks."},{"order":11,"type":"code","text":"import { defineConfig } from 'vite';
import { svelte } from '@sveltejs/vite-plugin-svelte';
import sveltePreprocess from 'svelte-preprocess';

export default defineConfig({
  plugins: [
    svelte({
      preprocess: sveltePreprocess({
        scss: {
          prependData: '@import "./src/styles/variables.scss";'
        }
      })
    })
  ]
});"},{"order":12,"type":"subheading","text":"4. Using SCSS in Svelte Components"},{"order":13,"type":"paragraph","text":"Once configured, you can directly use SCSS inside your Svelte components by adding the attribute 'lang="scss"' to your style tags."},{"order":14,"type":"code","text":"<script>
  let name = 'World';
</script>

<main>
  <h1>Hello {name}!</h1>
</main>

<style lang="scss">
  $primary-color: #ff3e00;

  main {
    padding: 1rem;
    h1 {
      color: $primary-color;
    }
  }
</style>"},{"order":15,"type":"subheading","text":"Best Practices"},{"order":16,"type":"bullet_point","text":"Always keep your 'svelte-preprocess' package updated to match your Svelte compiler version."},{"order":17,"type":"bullet_point","text":"Use the 'prependData' option sparingly, typically only for global variables, mixins, or functions."},{"order":18,"type":"bullet_point","text":"Leverage Vite's native asset handling for images and fonts referenced within your stylesheets."}]
